SELECT Go.IdP, Go.Sede, Go.Cognome, Go.Nome, Go.DataN, Comuni.Comune & " / " & Comuni.Slov AS Comune, Go.[davcna koda], Go.Via, Comuni_1.Comune & "/ " & Comuni_1.Slov AS ComuneR, Comuni_1.CAP, Go.tel, Go.mail, Go.cel, Go.PIscr, Scuola.AnnoS, Materia.Spricevalo, Scuola.Razred, Scuola.Voto, Scuola.Data, [Prof.Cognome] & " " & [Prof.Nome] AS NominativoP, Konservatori.Konservatori, LPPrVal.Solsko, Materia_1.Materia, Prof_1.Cognome, LPPrVal.Valutazione, Scuola.Livello, Materia_1.Stejemo, Scuola.Razred2, Scuola.Ore2, Scuola.DataI, Scuola.DataF, Scuola.DataI2, Scuola.DataF2, Go.DataD, Go.DataA, Go.DataE, Go.Motiv, Scuola.Ore, Scuola.Note
FROM ((((Materia RIGHT JOIN (Prof RIGHT JOIN ((([Go] LEFT JOIN Comuni ON Go.IdCN=Comuni.IdC) LEFT JOIN Comuni AS Comuni_1 ON Go.IdCR=Comuni_1.IdC) LEFT JOIN Scuola ON Go.IdP=Scuola.IdP) ON Prof.IdPr=Scuola.IdPr) ON Materia.IdM=Scuola.IdM) LEFT JOIN Konservatori ON Scuola.IdK=Konservatori.IdK) LEFT JOIN LPPrVal ON Go.IdP=LPPrVal.IdP) LEFT JOIN Materia AS Materia_1 ON LPPrVal.IdM=Materia_1.IdM) LEFT JOIN Prof AS Prof_1 ON LPPrVal.IdPr=Prof_1.IdPr
ORDER BY Go.Cognome, Go.Nome;
